<?php require_once 'includes/config.php'; require_login(); $role=$_SESSION['user']['role'];$uid=current_user_id();$error='';
function call_python_queue(string $action): ?array { $payload=json_encode(['action'=>$action,'token'=>PYTHON_API_TOKEN]);$ctx=stream_context_create(['http'=>['method'=>'POST','header'=>"Content-Type: application/json\r\n",'content'=>$payload,'timeout'=>2,'ignore_errors'=>true]]);$result=@file_get_contents(PYTHON_API_URL.'/queue/action',false,$ctx);if($result===false)return null;$data=json_decode($result,true);return is_array($data)?$data:null; }
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();require_roles(['admin','staff']);$action=$_POST['action']??'';if(in_array($action,['next','complete','skip'],true)){$api=call_python_queue($action);if($api && !empty($api['ok']))flash($api['message']??'Queue updated.');else{try{$pdo=db();$pdo->beginTransaction();if($action==='next'){$pdo->prepare("UPDATE queue_entries SET status='completed',completed_at=NOW() WHERE queue_date=CURDATE() AND status='serving'")->execute();$q=$pdo->query("SELECT id FROM queue_entries WHERE queue_date=CURDATE() AND status='waiting' ORDER BY queue_number ASC LIMIT 1 FOR UPDATE");$next=$q->fetch();if($next){$pdo->prepare("UPDATE queue_entries SET status='serving',called_at=NOW() WHERE id=?")->execute([$next['id']]);$msg='Next customer is now being served.';}else $msg='There are no waiting customers.';}elseif($action==='complete'){$q=$pdo->prepare("UPDATE queue_entries SET status='completed',completed_at=NOW() WHERE queue_date=CURDATE() AND status='serving'");$q->execute();$msg=$q->rowCount()?'Current customer marked completed.':'No customer is currently being served.';}else{$q=$pdo->prepare("UPDATE queue_entries SET status='skipped' WHERE queue_date=CURDATE() AND status='serving'");$q->execute();$msg=$q->rowCount()?'Current customer skipped.':'No customer is currently being served.';}$pdo->commit();flash($msg,$msg==='There are no waiting customers.'?'warning':'success');}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();flash('Queue action failed. Please try again.','error');}}header('Location: queue.php');exit;}}
if($role==='student'){$q=db()->prepare("SELECT q.*,a.service,a.appointment_time FROM queue_entries q LEFT JOIN appointments a ON a.id=q.appointment_id WHERE q.user_id=? ORDER BY q.queue_date DESC,q.queue_number DESC LIMIT 10");$q->execute([$uid]);$mine=$q->fetchAll();$todayServing=db()->query("SELECT queue_number FROM queue_entries WHERE queue_date=CURDATE() AND status='serving' ORDER BY id LIMIT 1")->fetchColumn();$waitingCount=(int)db()->query("SELECT COUNT(*) FROM queue_entries WHERE queue_date=CURDATE() AND status='waiting'")->fetchColumn();}else{$mine=[];$todayServing=db()->query("SELECT queue_number FROM queue_entries WHERE queue_date=CURDATE() AND status='serving' ORDER BY id LIMIT 1")->fetchColumn();$waitingCount=(int)db()->query("SELECT COUNT(*) FROM queue_entries WHERE queue_date=CURDATE() AND status='waiting'")->fetchColumn();$q=db()->query("SELECT q.*,u.full_name,a.service,a.appointment_time FROM queue_entries q JOIN users u ON u.id=q.user_id LEFT JOIN appointments a ON a.id=q.appointment_id WHERE q.queue_date=CURDATE() ORDER BY FIELD(q.status,'serving','waiting','skipped','completed'),q.queue_number");$all=$q->fetchAll();}
$pageTitle='Queue';require 'includes/header.php';?>
<div class="page-heading"><div><div class="eyebrow">LIVE QUEUE</div><h1>Queue management</h1><p class="muted">Queue numbers reset naturally by date. Only today's approved appointments appear here.</p></div><span class="live-pill"><span class="pulse"></span> Today's queue</span></div><div class="queue-overview"><article class="queue-now"><span>NOW SERVING</span><strong><?= $todayServing?'Q-'.str_pad((string)$todayServing,3,'0',STR_PAD_LEFT):'— — —' ?></strong><small><?= $todayServing?'Please proceed to the service desk.':'No customer is being served right now.' ?></small></article><article class="queue-metric"><span class="stat-icon amber">◷</span><small>Waiting</small><strong><?=$waitingCount?></strong><p class="muted">Customers in line today</p></article></div>
<?php if(in_array($role,['admin','staff'],true)):?><section class="panel"><div class="panel-heading"><div><h2>Queue controls</h2><p class="muted">Calling next automatically completes the current serving entry.</p></div></div><div class="queue-controls"><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><button class="btn primary" name="action" value="next">▶ Call next</button></form><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><button class="btn secondary" name="action" value="complete">✓ Mark completed</button></form><form method="post" onsubmit="return confirm('Skip the currently serving customer?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><button class="btn danger" name="action" value="skip">Skip current</button></form></div><p class="muted tiny">Python queue service is used when running. If it is offline, the PHP app safely handles these controls as a fallback.</p></section><section class="panel"><div class="panel-heading"><div><h2>Today's queue list</h2><p class="muted">Approved appointments for <?=e(date('F j, Y'))?></p></div><a class="text-link" href="manage.php">Approve appointments →</a></div><div class="table-wrap"><table><thead><tr><th>Queue</th><th>Student</th><th>Service</th><th>Appointment time</th><th>Status</th></tr></thead><tbody><?php if(!$all):?><tr><td colspan="5" class="empty">No approved queue entries for today.</td></tr><?php else:foreach($all as $r):?><tr><td><strong>Q-<?=str_pad((string)$r['queue_number'],3,'0',STR_PAD_LEFT)?></strong></td><td><?=e($r['full_name'])?></td><td><?=e($r['service']??'School service')?></td><td><?=e($r['appointment_time']?date('g:i A',strtotime($r['appointment_time'])):'—')?></td><td><span class="badge <?=e($r['status'])?>"><?=e(ucfirst($r['status']))?></span></td></tr><?php endforeach;endif;?></tbody></table></div></section><?php else:?><section class="panel"><div class="panel-heading"><div><h2>My queue numbers</h2><p class="muted">Approved appointments appear here after staff assign a number.</p></div></div><div class="table-wrap"><table><thead><tr><th>Queue</th><th>Service</th><th>Date</th><th>Status</th></tr></thead><tbody><?php if(!$mine):?><tr><td colspan="4" class="empty">You do not have a queue number yet. Book an appointment and wait for approval.</td></tr><?php else:foreach($mine as $r):?><tr><td><strong>Q-<?=str_pad((string)$r['queue_number'],3,'0',STR_PAD_LEFT)?></strong></td><td><?=e($r['service']??'School service')?></td><td><?=e(date('M j, Y',strtotime($r['queue_date'])))?></td><td><span class="badge <?=e($r['status'])?>"><?=e(ucfirst($r['status']))?></span><?php if($r['status']==='serving'):?><small>Please proceed to the service desk.</small><?php endif;?></td></tr><?php endforeach;endif;?></tbody></table></div></section><?php endif;?><?php require 'includes/footer.php';?>
